import { describe, expect, it } from 'vitest';
import { generateAILeaderboard } from '../src/leaderboard/generator';

describe('AI leaderboard generator', () => {
  it('generates 50+ deterministic AI leaderboard entries', () => {
    const first = generateAILeaderboard({ seed: 'arena-season-1', count: 64 });
    const second = generateAILeaderboard({ seed: 'arena-season-1', count: 64 });
    expect(first).toHaveLength(64);
    expect(first).toEqual(second);
    expect(new Set(first.map((entry) => entry.id)).size).toBe(64);
    expect(new Set(first.map((entry) => entry.displayName)).size).toBe(64);
  });

  it('entries satisfy profile and statistics invariants', () => {
    const entries = generateAILeaderboard({ seed: 42, count: 80 });
    expect(entries).toHaveLength(80);
    entries.forEach((entry, index) => {
      expect(entry.kind).toBe('bot');
      expect(entry.rank).toBe(index + 1);
      expect(entry.rating).toBeGreaterThanOrEqual(800);
      expect(entry.rating).toBeLessThanOrEqual(2400);
      expect(entry.stats.wins).toBeLessThanOrEqual(entry.stats.podiums);
      expect(entry.stats.podiums).toBeLessThanOrEqual(entry.stats.matchesPlayed);
      expect(entry.stats.holesInOne).toBeLessThanOrEqual(entry.stats.holesPlayed);
      expect(entry.stats.winRate).toBeGreaterThanOrEqual(0);
      expect(entry.stats.winRate).toBeLessThanOrEqual(1);
      if (index > 0) expect(entries[index - 1]!.rating).toBeGreaterThanOrEqual(entry.rating);
    });
  });
});
EOF
