import { describe, expect, it } from 'vitest';
import type { StorageLike } from '../src/core/SaveManager';
import { DEFAULT_SAVE_KEY, SaveManager, migrateSave } from '../src/core/SaveManager';
import { createDefaultProfile } from '../src/player/profile';
import { MAX_PLAYER_LEVEL, MAX_PLAYER_XP, levelForXp, xpForLevel } from '../src/player/progression';

class MemoryStorage implements StorageLike {
  private readonly data = new Map<string, string>();
  getItem(key: string): string | null {
    return this.data.get(key) ?? null;
  }
  setItem(key: string, value: string): void {
    this.data.set(key, value);
  }
  removeItem(key: string): void {
    this.data.delete(key);
  }
}

describe('progression curve', () => {
  it('covers levels 1 through 50', () => {
    expect(levelForXp(0)).toBe(1);
    expect(levelForXp(MAX_PLAYER_XP)).toBe(MAX_PLAYER_LEVEL);
    expect(xpForLevel(50)).toBeGreaterThan(xpForLevel(49));
  });
});

describe('SaveManager', () => {
  it('round trips a profile and derives level from XP', () => {
    const manager = new SaveManager(new MemoryStorage());
    const profile = createDefaultProfile(new Date('2026-01-01T00:00:00Z'), 'player-1');
    profile.displayName = 'Golfer';
    profile.progression.xp = xpForLevel(8);
    expect(manager.save(profile)).toBe(true);
    const loaded = manager.load();
    expect(loaded.displayName).toBe('Golfer');
    expect(loaded.progression.level).toBe(8);
  });

  it('falls back to a default profile on corrupt JSON', () => {
    const storage = new MemoryStorage();
    storage.setItem(DEFAULT_SAVE_KEY, '{broken');
    const profile = new SaveManager(storage).load();
    expect(profile.progression.level).toBe(1);
    expect(profile.displayName).toBe('Player');
  });

  it('reports storage write failure instead of throwing', () => {
    const failing: StorageLike = {
      getItem: () => null,
      setItem: () => {
        throw new Error('quota');
      },
      removeItem: () => {},
    };
    expect(new SaveManager(failing).save(createDefaultProfile())).toBe(false);
  });
});

describe('migrateSave', () => {
  it('accepts v1 flat XP and the retired hold control scheme', () => {
    const profile = migrateSave({
      version: 1,
      id: 'legacy',
      displayName: 'Old',
      xp: xpForLevel(5),
      settings: { controlScheme: 'hold' },
    });
    expect(profile.progression.level).toBe(5);
    expect(profile.settings.controlScheme).toBe('charge');
  });

  it('falls back when the save version is newer than this build', () => {
    const fallback = createDefaultProfile(new Date('2026-01-01T00:00:00Z'), 'fallback');
    const profile = migrateSave({ version: 999, profile: { progression: { xp: MAX_PLAYER_XP } } }, fallback);
    expect(profile.id).toBe('fallback');
    expect(profile.progression.level).toBe(1);
  });
});
EOF
